import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"FAQ & Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/05-faq-and-troubleshooting.md","filePath":"en/05-faq-and-troubleshooting.md"}'),i={name:"en/05-faq-and-troubleshooting.md"};function r(n,e,l,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; Troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to &quot;FAQ &amp; Troubleshooting&quot;">​</a></h1><blockquote><p><strong>Frequently Asked Questions, Debugging Tips, and Solutions</strong></p></blockquote><hr><h2 id="_1-frequently-asked-questions-faq" tabindex="-1">1. Frequently Asked Questions (FAQ) <a class="header-anchor" href="#_1-frequently-asked-questions-faq" aria-label="Permalink to &quot;1. Frequently Asked Questions (FAQ)&quot;">​</a></h2><h3 id="can-i-run-softforge-without-docker" tabindex="-1">Can I run SoftForge without Docker? <a class="header-anchor" href="#can-i-run-softforge-without-docker" aria-label="Permalink to &quot;Can I run SoftForge without Docker?&quot;">​</a></h3><p><strong>Yes.</strong> For prototyping and local development, run the FastAPI backend inside the Python virtual environment (<code>.venv</code>) and the frontend with <code>npm run dev</code>. Automated tests use an in-memory SQLite database, requiring no external services.</p><h3 id="how-does-dual-mode-authentication-work" tabindex="-1">How does dual-mode authentication work? <a class="header-anchor" href="#how-does-dual-mode-authentication-work" aria-label="Permalink to &quot;How does dual-mode authentication work?&quot;">​</a></h3><p>SoftForge accepts JWT tokens either via the <code>Authorization: Bearer &lt;token&gt;</code> header or via the <code>access_token</code> HttpOnly cookie. This provides security against XSS in web browsers while maintaining compatibility with curl, mobile apps, and external API clients.</p><h3 id="how-do-vertical-slices-share-data" tabindex="-1">How do vertical slices share data? <a class="header-anchor" href="#how-do-vertical-slices-share-data" aria-label="Permalink to &quot;How do vertical slices share data?&quot;">​</a></h3><p>Vertical slices should not import private models or services from other slices. Instead, they reference foreign entities via primitive UUIDs (<code>workspace_id</code>, <code>user_id</code>). Shared infrastructure logic belongs in <code>src/core/</code>.</p><hr><h2 id="_2-troubleshooting-common-issues" tabindex="-1">2. Troubleshooting Common Issues <a class="header-anchor" href="#_2-troubleshooting-common-issues" aria-label="Permalink to &quot;2. Troubleshooting Common Issues&quot;">​</a></h2><h3 id="issue-modulenotfounderror-no-module-named-greenlet" tabindex="-1">Issue: <code>ModuleNotFoundError: No module named &#39;greenlet&#39;</code> <a class="header-anchor" href="#issue-modulenotfounderror-no-module-named-greenlet" aria-label="Permalink to &quot;Issue: `ModuleNotFoundError: No module named &#39;greenlet&#39;`&quot;">​</a></h3><ul><li><strong>Cause:</strong> Async SQLAlchemy 2.0 requires <code>greenlet</code>.</li><li><strong>Fix:</strong> Run <code>pip install &quot;greenlet&gt;=3.0.0&quot;</code> in your virtual environment.</li></ul><h3 id="issue-port-8000-or-5173-already-in-use" tabindex="-1">Issue: <code>Port 8000 or 5173 already in use</code> <a class="header-anchor" href="#issue-port-8000-or-5173-already-in-use" aria-label="Permalink to &quot;Issue: `Port 8000 or 5173 already in use`&quot;">​</a></h3><ul><li><strong>Cause:</strong> A lingering process is holding the default ports.</li><li><strong>Fix:</strong> Change ports in <code>.env</code> (<code>API_PORT=8001</code>) or terminate the conflicting process.</li></ul><h3 id="how-to-reset-the-local-docker-database" tabindex="-1">How to reset the local Docker database? <a class="header-anchor" href="#how-to-reset-the-local-docker-database" aria-label="Permalink to &quot;How to reset the local Docker database?&quot;">​</a></h3><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>This flushes the <code>pgdata</code> volume and re-initializes Postgres with fresh tables.</p>',20)])])}const g=o(i,[["render",r]]);export{p as __pageData,g as default};
